R,C=19,16
g=[[4]*C for _ in range(R)]
ones=[(2,2),(4,14),(10,10),(17,9)]
sixes=[(4,4),(6,6),(7,14),(15,2)]
# Extend matching diagonal 1 pair, preserving isolated marks
for (r1,c1),(r2,c2) in [((2,2),(10,10))]:
    dr=1 if r2>r1 else -1; dc=1 if c2>c1 else -1
    for k in range(max(abs(r2-r1),abs(c2-c1))+1):
        r,c=r1+k*dr,c1+k*dc
        g[r][c]=1
# 6s aligned on that 1 diagonal project along the perpendicular diagonal
for r,c in sixes:
    if c-r == 0:
        for rr in range(R):
            cc=r+c-rr
            if 0<=cc<C:
                g[rr][cc]=6
# Restore all original marks, with 6 taking precedence
for r,c in ones:
    if g[r][c]!=6: g[r][c]=1
for r,c in sixes: g[r][c]=6
print('\n'.join(' '.join(map(str,row)) for row in g))
